        // empty-home-safe global qwen dir.
        expect(roots.homeConfineRoot).not.toBe('');
        expect(roots.homeConfineRoot).toBe(path.dirname(homeQwenDir));
        expect(roots.homeQwenDir).toBe(homeQwenDir);
